insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('sway-rear-mk7','cxca','sway-rear-mk7','Rear sway bar upgrade','Suspension','sway bar',array['rear sway bar','anti-roll bar','rsb','stabilizer bar','understeer','034','neuspeed','superpro']::text[],true,'1–2 hr',2) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('sway-front-mk7','cxca','sway-front-mk7','Front sway bar upgrade','Suspension','sway bar',array['front sway bar','fsb','anti-roll bar','stabilizer bar','subframe']::text[],true,'3–5 hr',4) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('endlinks-mk7','cxca','endlinks-mk7','Sway bar end links','Suspension','sway bar',array['end links','end link','drop link','clunk','rattle','stabilizer link','moog']::text[],true,'45 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('coilovers-mk7','cxca','coilovers-mk7','Coilovers & lowering springs','Suspension',null,array['coilovers','coilover','lowering springs','springs','lowering','dcc','kw','bilstein','st suspension','eibach','h&r','ride height','struts','shocks']::text[],true,'6–8 hr',3.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('sway-rear-mk7',$j${"id": "sway-rear-mk7", "title": "Rear sway bar upgrade", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI (all trims, multilink rear) · 2019+ Jetta GLI · A3 8V FWD · Mk8 GTI (same rear). Golf R and S3 use a 4Motion-specific bar", "category": "Suspension", "kind": "upgrade", "heroId": "mk7-rsb-hero", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$230–400", "risk": "Car on stands · muffler in the way · single-use bracket bolts", "why": "VW tuned the Mk7 to push wide before it ever steps out. A stiffer rear bar hands grip back to the front so the car turns in sharper and stays flatter, and it does it without touching the ride. On an MQB car it's the first handling change most owners make.", "note": "034's guide says about two hours; owners report closer to one. Snaking the bar past the muffler is the whole variable."}, "heroCap": "Looking up at the rear subframe. The bar sits in two brackets on the subframe with a short end link down to each lower control arm. Stock is 20 mm (21.3 on some early cars); upgrades run 22 to 26 mm.", "lifespan": {"title": "When owners do this", "headline": ["Usually the first or second handling mod, right after tires"], "earliest": null, "detail": "The stock bar doesn't wear out, so there's no failure mileage. Owners upgrade it when the car pushes wide in fast corners, and before springs or coilovers because it's cheaper, reversible, and doesn't change the ride.", "factors": ["Summer tires make the understeer more obvious", "Lowering springs stiffen the front, which strengthens the case for a rear bar"], "inspect": ["While you're under there: end link boots and bushings; the factory links are often tired by 60,000 miles"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus on ordering; end-link mileage is anecdotal."}}, "should": {"yesIf": ["The car understeers in fast corners and you'd like it more neutral", "Tires are done and you want the next real handling step", "You want a mod you can feel on the first drive", "You'd rather not change springs or dampers yet"], "codes": [], "notes": ["Rear-only is the classic first move on a front-wheel-drive car: the front already has plenty of roll stiffness, so stiffening the rear is what shifts the balance. Fitting a stiffer front bar first makes the understeer worse; 034 says so on their own front-bar sheet.", "Trade-offs: a stiffer rear bar lifts the inside rear wheel sooner in hard cornering, and on all-season tires in the rain the stiffest setting can make the tail livelier than you want. Start on the soft setting.", "This guide covers the GTI's multilink rear. Base Mk7 Golfs with the torsion-beam axle use a different bar; Golf R and S3 use a 4Motion-specific kit (034 402-1006, ECS 4Motion) and may need the suspension raised on a jack to reach the bracket bolts."], "confidence": {"level": "high", "n": 5, "note": "Consistent across 034 and ECS instructions, DAP's sizing article, and forum consensus."}}, "parts": [{"tier": "aftermarket", "name": "Rear sway bar kit (bar, bushings, brackets, hardware)", "pn": "see options below", "note": "Adjustable bars let you tune it later", "price": "$230–400", "links": []}, {"tier": "oe", "name": "Bracket bolts, M8 (×4)", "pn": "factory", "note": "Torque-to-yield style spec on the factory bolts; kits with their own brackets supply their own", "price": "$8", "links": []}, {"tier": "oe", "name": "End link nuts (×2)", "pn": "factory", "note": "Self-locking; replace if the nylon is tired", "price": "$4", "links": []}], "aftermarket": [{"name": "034Motorsport 22.2 mm solid, adjustable", "note": "Solid bar, billet brackets with grease fittings, Teflon bushings. 034 quotes +153% (soft) and +174% (stiff) over the factory 20 mm bar. The install guide is the reference for this one.", "price": "$280–330", "signal": "Best documented", "links": [{"store": "034 install guide (PDF)", "url": "https://www.034motorsport.com/docs/034-402-1008_Install_Instructions.pdf"}]}, {"name": "Neuspeed 25 mm, adjustable", "note": "Tubular, two-hole. Forum regulars put it at roughly double stock on the soft hole. Long-running default in Mk7 threads.", "price": "$270–320", "signal": "Forum favorite", "links": []}, {"name": "SuperPro 22 or 24 mm, adjustable", "note": "Two positions, poly bushings, the pick in more than one 'which bar' thread for a daily.", "price": "$240–280", "signal": "Value pick", "links": []}, {"name": "H&R 24 / 25 / 26 mm", "note": "Non-adjustable, tuned to the car; the 26 owner reports read 'more lift-off oversteer, no drawbacks'. Rubber-lined bushings that need no greasing.", "price": "$250–320", "signal": "Set-and-forget", "links": []}, {"name": "Whiteline 24 mm, adjustable · APR Roll-Control · Eurocode", "note": "All fit the same brackets and links. Whiteline is often bundled with their end links; Eurocode is adjustable without grease fittings.", "price": "$230–350", "signal": "Fine choices", "links": []}], "tools": [{"name": "Jack + two jack stands", "note": "final torque with the car on its wheels", "price": "$80–150"}, {"name": "10 mm triple-square (XZN) bit", "note": "factory bracket bolts; decent quality, not bargain-bin", "price": "$10"}, {"name": "6 mm triple-square bit + 16 mm wrench", "note": "the bit only holds the end-link stud; the wrench turns the nut", "price": "$18"}, {"name": "13 mm socket, exhaust hanger pliers", "note": "muffler hangers", "price": "$25"}, {"name": "Torque wrench, 20–60 Nm, plus an angle gauge or paint pen", "price": "$40–80"}, {"name": "Poly bushing grease, rubber mallet, tape to protect the bar's finish", "price": "$10"}], "before": ["Level ground, wheels chocked. Stands on the rear body jack points, never the subframe alone.", "Exhaust cold. You'll have your arms around the muffler.", "Check the kit: bar, two bushings, two brackets (if supplied), hardware. Where the kit gives its own torque values for its own hardware, those win.", "Both wheels off the ground together so the bar is unloaded."], "steps": [{"n": 1, "title": "Raise the rear and support it", "blocks": [{"t": "text", "b": "Jack the rear and set both stands. Wheels can stay on; you're working inboard of them. A creeper or cardboard makes the next hour nicer."}]}, {"n": 2, "title": "Drop the muffler", "blocks": [{"t": "text", "b": "Two hanger bolts on each side of the rear muffler, 13 mm. Take the bolts out and let the muffler hang on its pipe; you don't need to remove the cat-back. That inch or two of drop is what lets the bar come out."}, {"t": "note", "b": "ECS says 'lower or remove the cat-back'. Every owner account says the hanger bolts alone are enough."}]}, {"n": 3, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "Floor jack under each lower control arm in turn to take the load off the link. Put the 6 mm triple-square into the socket in the stud's tip to hold it, and turn the 16 mm nut off. Rotate the bar so each end drops out of its link; leave the links on the arms."}, {"t": "ill", "id": "mk7-endlink", "cap": "The bit only holds the stud still. Try to turn the bit and it strips. Turn the nut."}, {"t": "warn", "b": "One owner nearly snapped a link by forcing the triple-square. If the stud spins with the nut, the bit isn't seated; stop and re-seat it."}]}, {"n": 4, "title": "Unbolt the two brackets", "blocks": [{"t": "text", "b": "Two bolts per bracket into the subframe, 10 mm triple-square. Support the bar as the last one comes out."}]}, {"n": 5, "title": "Snake the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "Turn it, tip it, and feed it out over the passenger side past the muffler. If it won't clear, drop the muffler a little further. Owners split on which side is easier; passenger wins more often."}, {"t": "note", "b": "The factory brackets are tight on the bar. A rubber mallet knocks them off. Compare old and new bars side by side; the arm shape should match."}]}, {"n": 6, "title": "Bushings and brackets onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of each bushing with the kit's poly grease (never petroleum grease, which swells polyurethane; skip the grease entirely on rubber-lined H&R bushings). Slide them onto the bar at the same positions as the old ones, brackets over them. On 034 brackets the grease fitting points down."}, {"t": "note", "b": "Leave the plastic wrap on the bar until it's up in the car. Powder coat scratches easily on the subframe edges."}]}, {"n": 7, "title": "Feed the new bar in and start the bolts", "blocks": [{"t": "text", "b": "Reverse of step 5. Brackets up to the subframe, all four bolts started by hand. Snug, don't torque, so the bar can still rotate to meet the links."}]}, {"n": 8, "title": "Pick your setting and connect the links", "blocks": [{"t": "fork", "q": "Which hole?", "v": [{"label": "Outer (softer)", "when": "Start here", "blocks": [{"t": "text", "b": "A clear step up in turn-in and flatness with no drama. Drive it a week before you decide you want more."}]}, {"label": "Inner (stiffer)", "when": "Sticky tires, track days", "blocks": [{"t": "text", "b": "Sharper still, more inside-rear lift, livelier tail in the wet. Common second step, rare first one. Non-adjustable bars skip this choice."}]}]}, {"t": "text", "b": "Rotate the bar so the chosen hole lines up with each end-link stud, pass the stud through, start the nuts. Snug only."}]}, {"n": 9, "title": "Lower the car, then torque everything", "caution": true, "blocks": [{"t": "text", "b": "Bushings and links get their final torque with the weight on the wheels, not hanging on stands, or they're clamped at the wrong angle and you get clunks. Lower onto ramps, or onto the ground and reach under."}, {"t": "torque", "label": "Bracket bolts (M8, ×4) · factory hardware", "nm": 20, "note": "+90° turn", "c": {"level": "medium", "n": 2, "note": "ECS instructions and MyGolfMk7's manual-sourced table both give 20 Nm + 90°. If your kit supplied its own brackets and bolts, use the kit's figure: 034's 6 mm allen bolts are 28 Nm flat."}}, {"t": "torque", "label": "End link nuts at the bar (M10, ×2)", "nm": 55, "alt": [45, 35], "c": {"level": "varies", "n": 3, "note": "55 Nm is the factory value (ECS, MyGolfMk7). 034's sheets say 35 Nm (older) and 45 Nm (newer) for the same stock nut. We show the factory number; none of the three is wrong enough to matter, but don't guess higher."}}, {"t": "text", "b": "Muffler back on its hangers, 13 mm bolts snug."}]}, {"n": 10, "title": "Test drive and re-check", "blocks": [{"t": "text", "b": "Drive 20–50 miles with a few firm corners, then re-torque all six fasteners. Clunking over one-wheel bumps means a bracket or link is loose or a bushing wasn't greased."}]}], "alsoReplace": [{"name": "Rear end links", "why": "They're off the bar anyway. Factory links are tired by 60k and a stiffer bar loads them harder; Moog or adjustable links are the usual pairing."}, {"name": "Rear subframe inserts", "why": "Owners who did arms and inserts first say the bar change felt smaller afterwards. If the rear feels vague rather than soft, that's the fix."}], "check": {"tab": "Pick a setting", "title": "Which setting is right for you?", "illId": "mk7-rsb-hero", "illCap": "Both holes are on the same bar. Closer to the pivot is stiffer because the lever is shorter.", "rows": [{"see": "Daily driver, all-season tires", "means": "You want turn-in and less lean, not a tail that steps out in the rain.", "do": "Outer hole, or a 22–24 mm bar. Most people never move it."}, {"see": "Summer tires, spirited driving", "means": "The chassis can use more rear roll stiffness before it gets nervous.", "do": "Start outer, try inner after a week. Expect more inside-wheel lift."}, {"see": "Autocross or track", "means": "Balance matters more than comfort.", "do": "Inner, 25 mm or more, and adjustable end links so both sides preload evenly."}], "c": {"level": "community", "n": 4, "note": "DAP's sizing guide plus forum consensus. There is no factory guidance; this is a preference."}}, "aftercare": ["Re-torque after the first 20–50 miles, then forget about it.", "A squeak on slow bumps is a dry bushing; brackets with a grease fitting take a poly grease gun, otherwise pull the bracket and re-grease.", "Adjustable end links are the usual next step if you go to the stiff hole."], "disagreements": [{"topic": "Bracket bolt torque", "pos": "20 Nm + 90° (factory, via ECS and MyGolfMk7) vs 28 Nm flat (034's own hardware).", "call": "Factory value for factory bolts; kit value for kit bolts."}, {"topic": "End link nut torque", "pos": "55 Nm (ECS, MyGolfMk7) vs 35 Nm and 45 Nm (two 034 sheets).", "call": "55, flagged. Same nut, three numbers."}, {"topic": "Do you have to drop the exhaust?", "pos": "ECS: lower or remove the cat-back. Owners: hanger bolts out, let it sag.", "call": "Hanger bolts. Fully removing it is more work for no gain."}, {"topic": "Which side does the bar come out?", "pos": "Passenger (most) vs driver (one Eurocode owner).", "call": "Try passenger first."}], "sources": ["034Motorsport MQB FWD adjustable rear sway bar install guide (402-1008)", "ECS Tuning VW Mk7 solid rear sway bar installation (2021)", "MyGolfMk7 torque spec table (MQB manuals)", "GolfMK7 'My rear sway bar install experience' (2016)", "GolfMK7 034 rear sway bar review threads (2016, 2018)", "VWVortex 'Help selecting a rear sway bar', 'who is running an aftermarket rear sway'", "DAP 'Mk7 GTI rear sway bars explained' (2023)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('sway-front-mk7',$j${"id": "sway-front-mk7", "title": "Front sway bar upgrade", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI, Golf R · A3/S3 8V · TT 8S (same MQB front subframe)", "category": "Suspension", "kind": "upgrade", "heroId": "mk7-fsb-drop", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr on a lift", "difficulty": 4, "cost": "$300–450 + alignment", "risk": "Subframe on a jack · a dozen single-use stretch bolts · alignment afterwards", "why": "The rear bar changed the car's balance. The front bar is about grip: less roll keeps the outside front tire flatter on the road, so a strut car like this one stops giving away camber mid-corner. On the MQB the bar hides between the subframe and the steering rack, so the subframe comes down to reach it.", "note": "034 rates their own guide 'Spicy' and recommends a shop. The good news versus the Mk5: the steering column, ball joints and tie rods all stay connected."}, "heroCap": "The bar lives in the channel between the subframe and the steering rack. Six bolts hold the subframe to the body and its brace; loosen them, lower it four inches on a jack, and the bar comes out the back.", "lifespan": {"title": "When owners do this", "headline": ["After the rear bar and tires, often with coilovers while the subframe is already down"], "earliest": null, "detail": "The stock bar doesn't wear out. Owners add a front bar when the rear is done and the front still washes out, or fold it into a bigger suspension job.", "factors": ["Rear bar already installed", "Coilovers going in", "Track days"], "inspect": ["While the subframe is down: dogbone (pendulum) mount and front control-arm bushings"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus on ordering; the bar itself is a preference."}}, "should": {"yesIf": ["You've done the rear bar and the front still pushes", "You want flatter cornering without a harsher ride", "You're already dropping the subframe for something else", "You have a helper, a second jack and a torque wrench that reads angle"], "codes": [], "notes": ["Rear first. 034's front-bar sheet says in so many words that a stiffer front bar on a car with the factory rear bar increases understeer. Do them in the right order, or together.", "Not dangerous once the car is on stands, but a subframe on a floor jack wants a second person, and the alignment afterwards is not optional. Toe and camber are set by where the subframe lands.", "Fewer front bars exist for the MQB than for the Mk5 because the job is this involved. 034 and H&R are the two with public documentation."], "confidence": {"level": "high", "n": 3, "note": "Method from the manufacturer guide; torque values cross-checked against MyGolfMk7's manual-sourced table with two disagreements shown below."}}, "parts": [{"tier": "aftermarket", "name": "Front sway bar kit (bar, bushings, brackets, grease)", "pn": "see options below", "note": "034 ships allen bracket bolts; check that the kit's bushings match your bar diameter", "price": "$300–450", "links": []}, {"tier": "oe", "name": "Subframe and brace bolts, M12 (×8)", "pn": "single-use", "note": "Every 70 Nm + 180° bolt below is a stretch bolt. Replace", "price": "$40–60", "links": []}, {"tier": "oe", "name": "Steering rack bolts (×2), dogbone bolts (×2), brace-to-body bolts (×4)", "pn": "single-use", "note": "Also angle-torqued; replace", "price": "$30", "links": []}, {"tier": "oe", "name": "End-link nuts (×2)", "pn": "self-locking", "note": "Replace whenever removed", "price": "$4", "links": []}], "aftermarket": [{"name": "034Motorsport solid, adjustable", "note": "Two-hole adjustable, poly bushings, billet brackets with grease fittings. The 38-step install guide is the reference for this whole guide (photographed on an S3; same subframe).", "price": "$400–450", "signal": "Best documented", "links": [{"store": "034 install guide (PDF)", "url": "https://www.034motorsport.com/docs/034motorsport-adjustable-mqb-solid-front-sway-bar-install-guide-diy-034-402-1009.pdf"}]}, {"name": "H&R 28 mm, adjustable (70787-28)", "note": "Two-point adjustable, sold for the 2015–19 GTI, also as a front-and-rear set. Rubber-lined bushings, no greasing.", "price": "$380–410", "signal": "Set-and-forget", "links": []}], "tools": [{"name": "Floor jack + two stands, plus a second jack (a transmission jack is ideal) for the subframe", "note": "a board on the jack pad spreads the load"}, {"name": "Sockets: 10, 13, 16, 18 mm 6-point · 6 mm triple-square (end links) · T25 · 6 mm allen (034 brackets)", "note": "6-point on the 18s; they are very tight"}, {"name": "Torque wrench to 120 Nm and an angle gauge (or a paint pen and a protractor's worth of patience)"}, {"name": "Long extension for the subframe bolts, pry bar, penetrating oil, paint pen for reference marks"}], "before": ["Level ground. Stands on the body jack points, never under the subframe you're about to drop.", "Raise both sides of the front together; one side up puts the bar under load.", "Mark the subframe's outline on the body with a paint pen before a bolt comes out. The vendor guide doesn't say to; every owner who skipped it wished they hadn't.", "Book an alignment for afterwards. 034 calls a four-wheel alignment 'highly recommended'; treat it as required.", "Read the whole procedure once. Steps 6 to 11 all have to be done before the subframe will move, and nothing gets torqued until step 17."], "steps": [{"n": 1, "title": "Wheels off, wind deflector off", "blocks": [{"t": "text", "b": "Loosen the lug bolts (17 mm) on the ground, raise both sides, stands under the body, wheels off. Remove the plastic wind deflector under the nose: two T25 screws and two push-centre clips."}]}, {"n": 2, "title": "Downpipe hanger and oil level sensor", "blocks": [{"t": "text", "b": "Two 13 mm bolts hold the downpipe hanger to the rear of the subframe; remove them and leave the hanger on the downpipe. Unplug the oil level sensor connector on the bottom of the oil pan and unclip its lead from the top of the subframe."}]}, {"n": 3, "title": "End links off the bar", "blocks": [{"t": "text", "b": "16 mm on the lower nut of each end link where it meets the bar; if the stud turns, hold it with a 6 mm triple-square. Swing the links clear."}]}, {"n": 4, "title": "Level sensor", "blocks": [{"t": "text", "b": "Unplug the suspension level sensor (driver's side; cars with xenon or LED headlights) and remove the 10 mm bolt holding its bracket to the subframe. Note how the arm sits so it goes back the same."}]}, {"n": 5, "title": "Steering rack bolts", "blocks": [{"t": "text", "b": "Two 18 mm bolts secure the steering rack to the subframe. Remove them. The rack stays connected to the column and will lift off its locating bosses when the subframe drops."}]}, {"n": 6, "title": "Subframe brace", "blocks": [{"t": "text", "b": "Four 16 mm bolts hold the brace to the chassis; two 18 mm bolts hold it to the subframe. All six out."}]}, {"n": 7, "title": "Dogbone (pendulum mount)", "blocks": [{"t": "text", "b": "Two 16 mm bolts into the bottom of the transmission. Remove them; the mount stays on the subframe."}]}, {"n": 8, "title": "Jack under the subframe, then the two big bolts", "caution": true, "blocks": [{"t": "text", "b": "Second jack, with a board, snug under the middle of the subframe. Now the one 18 mm bolt on each side that holds the subframe to the chassis. 034's hint: run the extension through the stamped hole in the control arm to reach it."}, {"t": "warn", "b": "From here the jack is the only thing holding a heavy subframe. Have your helper steady it, and keep every part of you out from under it."}, {"t": "ill", "id": "mk7-fsb-drop", "cap": "Six bolts free the subframe: two to the body, two brace-to-body pairs, two brace-to-subframe. The rack lifts off its bosses as it drops."}]}, {"n": 9, "title": "Lower the subframe", "blocks": [{"t": "text", "b": "Lower the jack slowly and evenly, watching two things: the steering rack, which needs to come free of its bosses, and the oil level sensor lead, which must not get pinched. About four inches is enough."}]}, {"n": 10, "title": "Old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "Four 13 mm bolts hold the factory bar's brackets to the subframe. Remove them and pull the bar out from the back of the subframe. The bushings snag on the rack; patience beats force."}]}, {"n": 11, "title": "Brackets and bushings onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of the poly bushings with the kit's grease (never petroleum grease). Slide them on, brackets over them. On 034 brackets, orient the grease fitting toward the front of the car."}]}, {"n": 12, "title": "New bar into the subframe", "blocks": [{"t": "text", "b": "Bar into the channel from the back, brackets aligned with the subframe holes, four bracket bolts in."}, {"t": "torque", "label": "Sway bar bracket bolts (×4)", "nm": 40, "alt": [20], "c": {"level": "varies", "n": 2, "note": "40 Nm is 034's figure for their own 6 mm allen bolts. The factory 13 mm bolts are 20 Nm + 180° (MyGolfMk7 table). Torque whichever bolt you're actually holding to its own number."}, "note": "factory bolts: 20 Nm + 180°"}, {"t": "text", "b": "Route the oil level sensor lead underneath the new bar now, before the subframe goes up."}]}, {"n": 13, "title": "Raise the subframe and seat the rack", "caution": true, "blocks": [{"t": "text", "b": "Raise the jack until the subframe meets the body. As it comes up, align the bosses on the steering rack into their holes in the subframe and press them home; a rack that isn't seated is a loose rack. Start the two subframe-to-chassis bolts loosely."}, {"t": "warn", "b": "Nothing gets torqued until the subframe sits on your paint marks. One bolt tightened early locks it in the wrong place and the alignment shop will send you back under the car."}]}, {"n": 14, "title": "Brace, rack and dogbone", "blocks": [{"t": "text", "b": "Start all the remaining bolts by hand first: brace to subframe, brace to chassis, rack, dogbone. Then nudge the subframe onto your marks. Only now torque, in this order."}, {"t": "torque", "label": "Brace to subframe (M12 ×2, NEW)", "nm": 70, "note": "+180° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 180°: 034 guide and MyGolfMk7 agree."}}, {"t": "torque", "label": "Brace to chassis (×4, NEW)", "nm": 20, "alt": [50], "note": "+90° turn", "c": {"level": "varies", "n": 2, "note": "034's guide says 20 Nm + 90°; MyGolfMk7's manual-sourced table says 50 Nm + 90° for the same bolts. Same angle, different base. We show 034's because it's the procedure we followed; if you can check the bolt grade against the manual, do."}}, {"t": "torque", "label": "Steering rack bolts (M12 ×2, NEW)", "nm": 70, "note": "+90° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 90°: 034 and MyGolfMk7."}}, {"t": "torque", "label": "Dogbone to transmission (×2, NEW)", "nm": 50, "note": "+90° turn", "c": {"level": "high", "n": 2, "note": "50 Nm + 90°: 034 and MyGolfMk7."}}]}, {"n": 15, "title": "Sensors and hanger back", "blocks": [{"t": "text", "b": "Oil level sensor plugged in and its lead clipped to the subframe. Level sensor bracket (10 mm) and connector. Downpipe hanger, two 13 mm bolts."}]}, {"n": 16, "title": "End links", "blocks": [{"t": "text", "b": "Nuts back onto the end-link studs at the bar. On an adjustable bar the outer hole is soft, the inner hole stiff; start soft."}, {"t": "torque", "label": "End-link nuts at the bar (×2)", "nm": 65, "c": {"level": "high", "n": 2, "note": "65 Nm: 034 guide and MyGolfMk7 table."}}]}, {"n": 17, "title": "Subframe bolts last", "caution": true, "blocks": [{"t": "text", "b": "Check everything is aligned and torqued. Then the two 18 mm subframe-to-chassis bolts."}, {"t": "torque", "label": "Subframe to chassis (M12 ×2, NEW)", "nm": 70, "note": "+180° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 180°: 034 and MyGolfMk7."}}]}, {"n": 18, "title": "Deflector, wheels, alignment", "blocks": [{"t": "text", "b": "Wind deflector back on. Wheels on at 120 Nm. Drive gently to the alignment shop and tell them the subframe was lowered. Re-check the end links after 50 miles."}]}], "alsoReplace": [{"name": "Dogbone (pendulum) mount insert", "why": "It's unbolted from the transmission anyway. A poly insert is $40 and ten minutes here, and it's the usual cure for drivetrain clunk and sloppy shifts on these cars."}, {"name": "Front end links", "why": "They're off the bar. If the boots are cracked or the joints have play, new ones now."}, {"name": "Subframe locking collars / alignment kit", "why": "Replaces the subframe's slop with locating sleeves so it can't shift under load. Only sensible while the bolts are already out."}], "check": {"tab": "Pick a setting", "title": "Which hole, if your bar is adjustable?", "illId": "mk7-fsb-drop", "illCap": "Same logic as the rear bar: the hole closer to the pivot is stiffer.", "rows": [{"see": "Street car, all-season or touring tires", "means": "You want the roll reduction without changing balance much.", "do": "Outer (soft) hole. Most stay here."}, {"see": "Summer tires, already on the stiff rear setting", "means": "The car may have gone tail-happy; the front bar brings balance back.", "do": "Soft hole first, then stiff if the front still rolls more than the rear."}, {"see": "Track use", "means": "You'll tune front and rear together per event.", "do": "Stiff hole, adjustable end links both ends."}], "c": {"level": "community", "n": 3, "note": "Forum consensus and 034's own soft/stiff labelling."}}, "aftercare": ["Alignment within the first drive or two. Not optional.", "Re-torque end links after 50 miles.", "Poly bushings squeak when dry; grease at the first squeak.", "Clunk from the front on take-off after this job: check the dogbone bolts."], "disagreements": [{"topic": "Brace-to-chassis torque", "pos": "034: 20 Nm + 90°. MyGolfMk7 (from the MQB manual): 50 Nm + 90°.", "call": "Shown as a range, flagged. The angle is the same; check the bolt grade if you can."}, {"topic": "How hard is it?", "pos": "034: 'Spicy', professional installation recommended. Owners on the forums: an afternoon with a helper and a second jack.", "call": "4 out of 5. Doable in a driveway if you've done the rear bar and have the tools."}, {"topic": "Mark the subframe?", "pos": "The vendor guide doesn't mention reference marks.", "call": "Mark it. The alignment shop can only fix so much."}], "sources": ["034Motorsport adjustable MQB solid front sway bar install guide (402-1009)", "MyGolfMk7 torque spec table (MQB manuals)", "GolfMK7 and VWVortex front-bar and 'front is a 5-hour job' threads", "H&R 70787-28 listing (fitment, adjustability)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('endlinks-mk7',$j${"id": "endlinks-mk7", "title": "Sway bar end links", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R (front and rear links are common) · A3/S3 8V · Mk8 GTI", "category": "Suspension", "kind": "repair", "heroId": "mk7-endlink", "variants": {"question": "Front or rear?", "hint": "Front links run from the sway bar up to a bracket on the strut. Rear links run from the bar down to the lower control arm and are bolted through it. Same technique, different fasteners.", "options": [{"id": "front", "label": "Front end links", "when": "16 mm nut (18 on some cars), 6 mm triple-square"}, {"id": "rear", "label": "Rear end links", "when": "16 mm at the bar, 13 mm bolt and nut through the control arm"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$30–250 a pair", "risk": "Car on stands · seized nuts · a stretch bolt at the rear", "why": "End links are the two little rods that connect the sway bar to the suspension. When their joints wear, the bar rattles instead of working, and you hear it as a clunk over every manhole cover. On a Mk7 the factory links are the weak point behind most 'is my sway bar loose?' threads.", "note": "034, ECS and MyGolfMk7 agree on the procedure to the fastener. Seized nuts are the only variable."}, "heroCap": "Front link: bar to strut bracket. Rear link: bar to lower control arm. Each stud has a socket in its tip so you can hold it while the nut turns.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front links: commonly loose or rattling past 60,000–90,000 miles", "only": ["front"]}, {"text": "Rear links: often still fine past 100,000; check whenever the bar is off", "only": ["rear"]}], "earliest": "Sooner on cars with stiffer aftermarket bars, which load the joints harder", "detail": "The symptom is a hollow clunk from one corner over small bumps, worst at low speed. Grab the link with the car on stands and wiggle: any play in the joint, or a torn boot, and it's done.", "factors": ["Aftermarket sway bar", "Lowered car (links at an angle)", "Salt-belt corrosion"], "inspect": ["Check whenever you're under the car with a wheel off"], "confidence": {"level": "community", "n": 3, "note": "Owner reports and vendor notes; no factory interval. Mileage is anecdotal."}}, "should": {"yesIf": ["Clunk or rattle from a corner over small bumps", "Visible play when you wiggle the link by hand", "Torn or missing rubber boot on a joint", "You just fitted a stiffer bar and the old links have miles on them"], "codes": [], "notes": ["Both sides. If one has worn, the other is close, and a mismatched pair loads the bar unevenly.", {"text": "Rear links bolt through the lower control arm with a 13 mm bolt that VW angle-torques (20 Nm + 180°). That's a single-use stretch bolt; buy two.", "only": ["rear"]}, {"text": "Adjustable or spherical links (034, Whiteline, SuperPro) let you set the length so the bar sits unloaded at rest, which matters once the car is lowered or the bar is on its stiff setting. Heim-joint types are noisier and want greasing; 034's ship with spacers that go in a specific order.", "only": ["front", "rear"]}], "confidence": {"level": "high", "n": 3, "note": "Symptoms and technique agree across vendor guides and forum threads."}}, "parts": [{"tier": "oe", "name": "Front end link, OEM (each)", "pn": "Lemförder / TRW / Meyle HD", "note": "Lemförder is the OE maker", "price": "$25–45", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear end link, OEM (each)", "pn": "Lemförder / Meyle HD", "note": "", "price": "$20–35", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Self-locking nuts (×2 per link)", "pn": "factory", "note": "Replace every time they come off", "price": "$6", "links": []}, {"tier": "oe", "name": "Control-arm bolts, M8 (×2)", "pn": "single-use", "note": "Angle-torqued; replace", "price": "$6", "links": [], "only": ["rear"]}], "aftermarket": [{"name": "Moog K750809 (rear)", "note": "Bigger joints than OE at OE length. The cheap, common answer to a rear rattle on a stock-height car; often paired with a Neuspeed or 034 bar.", "price": "$40–70 a pair", "signal": "Budget pick", "links": []}, {"name": "034Motorsport spherical end links", "note": "Spherical bearings, adjustable, with spacers that stack in a set order (two long at the bottom, one short at the top on the rear). Meant for lowered or track cars; 034 torques their own hardware to 45 Nm.", "price": "$150–250 a pair", "signal": "Track pick", "links": [{"store": "034 rear end link guide (PDF)", "url": "https://www.034motorsport.com/docs/034-402-4019_Install_Instructions.pdf"}]}, {"name": "Whiteline / SuperPro adjustable", "note": "Adjustable length, rubber or poly boots, quieter than heim joints. Whiteline bundles theirs with their bars.", "price": "$120–170 a pair", "signal": "Worth it if lowered", "links": []}], "tools": [{"name": "Jack + two stands; 17 mm for the lug bolts"}, {"name": "16 mm and 18 mm wrenches (ratcheting open-end is ideal) and a 6 mm triple-square bit", "only": ["front"]}, {"name": "16 mm wrench, 13 mm socket and wrench, 6 mm triple-square bit", "only": ["rear"]}, {"name": "Penetrating oil, wire brush, torque wrench to 65 Nm, angle gauge or paint pen"}], "before": ["Raise both sides of that axle together. One wheel up loads the bar and the links won't come off without a fight.", "Soak the nuts with penetrating oil while you get the wheels off.", "A floor jack under the control arm to take the load off the link makes both the removal and the alignment of the new one much easier.", "Final torque happens with the car back on its wheels."], "steps": [{"n": 1, "title": "Raise the axle, wheels off", "blocks": [{"t": "text", "b": "Lugs loose on the ground, raise both sides of the axle, stands under the body, wheels off."}]}, {"n": 2, "title": "Find the link", "blocks": [{"t": "text", "b": "Behind the strut, a short rod from the end of the sway bar up to a bracket on the strut. Two nuts: one at the bar, one at the strut.", "only": ["front"]}, {"t": "text", "b": "Inboard of the wheel, a short rod from the end of the sway bar down to the lower control arm. A nut on a stud at the bar; a bolt and nut through the arm at the bottom.", "only": ["rear"]}, {"t": "ill", "id": "mk7-endlink", "cap": "Triple-square in the stud's tip to hold it still; the wrench on the nut does the turning."}]}, {"n": 3, "title": "Remove the fasteners", "blocks": [{"t": "text", "b": "16 mm on the nuts (some cars use an 18 at the strut end; bring both). If the whole stud spins, put the 6 mm triple-square into the socket in the stud's tip and hold it while you turn the nut. Work a seized nut back and forth rather than forcing it, and re-oil. No heat; the boot won't survive it.", "only": ["front"]}, {"t": "text", "b": "At the bar: 16 mm on the nut, 6 mm triple-square holding the stud if it spins. At the arm: 13 mm socket on the bolt, 13 mm wrench on the nut; tap the bolt through with a soft mallet once the nut is off. Jack the arm up or down a little if the bolt binds.", "only": ["rear"]}, {"t": "note", "b": "The bar isn't under load with both wheels up. Nothing springs when the link comes off."}]}, {"n": 4, "title": "Swap the link", "blocks": [{"t": "text", "b": "Pull the old link out, compare lengths with the new one, and fit the new one the same way round. Start new self-locking nuts by hand at both ends. Snug only.", "only": ["front"]}, {"t": "text", "b": "Fit the new link, new bolt through the arm with the nut started, new nut on the stud at the bar. Adjustable links: set them to the factory length first, then fine-tune on the ground so the bar sits with no preload. Snug only.", "only": ["rear"]}]}, {"n": 5, "title": "Other side", "blocks": [{"t": "text", "b": "Repeat. Both sides, always."}]}, {"n": 6, "title": "Wheels on, car down, then torque", "blocks": [{"t": "text", "b": "Wheels on (120 Nm), lower the car, roll it a foot to settle. Then torque with the weight on the wheels so the joints aren't clamped at a strange angle."}, {"t": "torque", "label": "Front end-link nuts (both ends)", "nm": 65, "c": {"level": "medium", "n": 2, "note": "65 Nm at the bar: 034 front-bar guide and MyGolfMk7. The strut end is assumed the same M10 nut; no separate figure was found."}, "only": ["front"]}, {"t": "torque", "label": "Rear end-link nut at the bar", "nm": 55, "alt": [45], "c": {"level": "varies", "n": 3, "note": "55 Nm factory (ECS, MyGolfMk7); 034 says 45 Nm for their own spherical-link hardware."}, "only": ["rear"]}, {"t": "torque", "label": "Rear end-link bolt through the control arm (NEW)", "nm": 20, "note": "+180° turn", "c": {"level": "medium", "n": 2, "note": "20 Nm + 180° (MyGolfMk7, from the manual); 034 uses 35 Nm flat with their supplied lock nut. Factory bolt gets the factory angle."}, "only": ["rear"]}]}], "alsoReplace": [{"name": "Sway bar bushings", "why": "Rear bushings are two bolts away once the links are off, and a dry rubber bushing is the other source of the same squeak."}], "check": {"tab": "Is it the link?", "title": "Is the noise really the end link?", "illId": "mk7-endlink", "illCap": "Wiggle test: any play here, or a torn boot, is a bad link.", "rows": [{"see": "Hollow clunk over small bumps, one corner, low speed", "means": "Classic end link. Confirm with the wiggle test.", "do": "Replace both links on that axle."}, {"see": "Creak or groan when turning into a driveway", "means": "More likely the sway bar bushings or a strut top mount.", "do": "Check bushings first; they're cheaper."}, {"see": "Knock on acceleration or gear change", "means": "Drivetrain mount, usually the dogbone.", "do": "Different job; see the front sway bar guide's 'while you're in there'."}], "c": {"level": "community", "n": 3, "note": "Forum diagnosis threads plus vendor articles."}}, "aftercare": ["Re-check torque after 50 miles.", "If a new link rattles immediately, the nut was torqued in the air or an adjustable link is the wrong length."], "disagreements": [{"topic": "Nut size at the front", "pos": "16 mm (034, MyGolfMk7) vs 18 mm (FCP Euro's coilover DIY).", "call": "Bring both."}, {"topic": "Rear torque", "pos": "55 Nm factory vs 45 Nm (034 hardware).", "call": "Factory value for factory nuts; kit value for kit hardware."}], "sources": ["034Motorsport MQB spherical rear sway bar end link guides (402-4019, two revisions)", "034Motorsport MQB front sway bar guide (end-link steps)", "ECS Tuning Mk7 rear sway bar instructions", "MyGolfMk7 torque spec table", "FCP Euro Mk7 coilover install (front link access)", "GolfMK7 / VWVortex end-link and rattle threads"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('coilovers-mk7',$j${"id": "coilovers-mk7", "title": "Coilovers & lowering springs", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI (all trims; DCC and strut diameter vary by trim) · Golf R and S3 use their own spring rates and rear geometry", "category": "Suspension", "kind": "upgrade", "heroId": "mk7-coilover-hero", "variants": {"questions": [{"question": "What's going in?", "hint": "Coilovers replace the struts, springs and rear shocks with height-adjustable (often damping-adjustable) units. Lowering springs keep the factory dampers and only change the springs.", "options": [{"id": "coil", "label": "Coilovers", "when": "Full kit: struts, springs, rear shocks. Adjustable height."}, {"id": "springs", "label": "Lowering springs", "when": "Springs only, on the factory dampers. Cheaper, keeps DCC."}]}, {"question": "Does your car have DCC?", "hint": "Dynamic Chassis Control is VW's adjustable damping: a Comfort / Normal / Sport choice in the Mode menu and a wire plugged into each strut and shock. Standard on Autobahn and Performance Pack cars; look for the connector on the strut.", "options": [{"id": "dcc", "label": "Yes, DCC", "when": "Wire into each damper; Mode menu has a suspension setting"}, {"id": "nodcc", "label": "No DCC", "when": "Plain dampers, no plug"}]}]}, "glance": {"timeFirst": "6–8 hr (a full day)", "timeRepeat": "4 hr", "difficulty": 3.5, "cost": "$300–600 (springs) · $900–2,800 (coilovers) · + alignment", "risk": "Compressed springs · a dozen stretch bolts · DCC faults · headlight aim", "why": "This is the biggest single change you can make to how the car drives, and the most involved bolt-on in the Mk7 catalog so far. Coilovers let you set height and often damping; springs give you the drop and a firmer rate on the dampers you already have. On a Mk7 two things decide which kit you can buy before you decide which one you want: DCC, and the diameter of your front struts.", "note": "Vendor videos run an hour. Owners report a full day, two if a pinch bolt fights. The alignment afterwards is not optional."}, "heroCap": "Front: the strut clamps into the wheel bearing housing with one pinch bolt and a spring-steel anti-rotation tab, and hangs from three bolts under the cowl. Rear: a separate spring in the lower control arm and a shock on two upper bolts and one big lower bolt.", "lifespan": {"title": "When owners do this", "headline": ["Usually after tires and a rear bar, or when the original dampers are done around 80,000–100,000 miles"], "earliest": null, "detail": "Original dampers are tired by then: bouncy ride, nose-dive under braking, inner-edge tire wear. Owners choosing between new factory-style dampers and coilovers often go coilover because the price gap has closed. Springs are the cheaper middle path if the dampers are still good.", "factors": ["Worn original dampers", "Rear bar already fitted", "Want the stance"], "inspect": ["Bounce test each corner: more than one rebound means the damper is gone"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus; no factory interval for dampers."}}, "should": {"yesIf": ["Original dampers are worn", "You want adjustable ride height, or a set drop", "Rear bar is done and you want the next step", "You have a full day, a helper, and an alignment booked"], "codes": [], "notes": ["Measure your front struts before you order anything. VW fitted both 50 mm and 55 mm (54.5) strut housings to the Mk7 with no reliable pattern by trim or year. Coilover struts and many spring kits are sold by diameter, and the wrong one won't clamp in the knuckle. A digital caliper on the strut body just above the knuckle takes thirty seconds.", {"text": "DCC plus coilovers means the car loses its adjustable dampers, and the DCC module throws a fault when it can't find them. Two ways out: a canceller kit (KW 68510342, iSWEEP IS.EC.MK7, Silvers) that plugs into the four damper connectors and fakes the load, or a DCC-compatible coilover (Bilstein B16 DampTronic, KW DDC plug-and-play) that keeps the button working. Budget for one or the other; a coded-out DCC is a workaround, not a fix.", "only": ["coil+dcc"]}, {"text": "Springs keep DCC. The dampers stay, the wiring stays, the button works. Buy a spring listed for DCC cars: APR, EMD and Eibach publish separate rates and drops for DCC and non-DCC dampers because the factory DCC struts are a different length.", "only": ["springs+dcc"]}, {"text": "No DCC keeps this simple: any Mk7 GTI coilover or spring kit fits, subject to the strut diameter above.", "only": ["nodcc"]}, "Buy the install kit, or its parts: new strut bearings (5Q0 412 249 F), pinch bolts (N 909 548 02), strut top nuts (N 101 064 02), strut mount bolts (N 912 464 01), rear shock mounts. Half are torque-to-yield and all of them are nearly a decade old. DAP sells them as a bundle for non-DCC cars.", "Lower it sensibly. Below about 1.5 inches the MQB geometry goes off, inner tires wear fast, and you'll want camber correction and adjustable end links. Xenon and LED cars also need the headlight leveling re-taught after any height change (see step 14)."], "confidence": {"level": "high", "n": 5, "note": "Procedure from FCP Euro's Mk7 install and the GolfMK7 reference guide; torque values from MyGolfMk7's manual-sourced table with the one disagreement shown; DCC and diameter points from vendor listings and owner threads."}}, "parts": [{"tier": "aftermarket", "name": "Coilover kit (4 corners)", "pn": "see options below", "note": "Ordered by strut diameter (50 or 55 mm)", "price": "$900–2,800", "links": [], "only": ["coil"]}, {"tier": "aftermarket", "name": "Lowering spring set", "pn": "see options below", "note": "Ordered by DCC / non-DCC", "price": "$300–600", "links": [], "only": ["springs"]}, {"tier": "aftermarket", "name": "DCC canceller kit (4 modules)", "pn": "KW 68510342 · iSWEEP IS.EC.MK7 · Silvers", "note": "Plugs into the four factory damper connectors. Not needed with a DCC-compatible coilover", "price": "$150–300", "links": [], "only": ["coil+dcc"]}, {"tier": "oe", "name": "Front strut bearings (×2)", "pn": "5Q0 412 249 F", "note": "Reused by most coilover kits; replace them", "price": "$40–60", "links": []}, {"tier": "oe", "name": "Pinch bolts (×2) and strut top nuts (×2)", "pn": "N 909 548 02 · N 101 064 02", "note": "Torque-to-yield; replace", "price": "$20", "links": []}, {"tier": "oe", "name": "Strut mount bolts (×6)", "pn": "N 912 464 01", "note": "Angle-torqued; replace", "price": "$12", "links": []}, {"tier": "oe", "name": "Rear shock mounts (×2), lower shock bolts, knuckle bolts", "pn": "factory / 034 Street Density", "note": "Cheap rubber on a ten-year-old car; the bolts are single-use", "price": "$50–90", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Book it for the day after", "price": "$100–150", "links": []}], "aftermarket": [{"name": "KW V1 / V2 / V3 (and DDC plug-and-play for DCC cars)", "note": "Stainless bodies, reuse factory bearings. V1 fixed, V2 rebound, V3 rebound and compression. The DDC version talks to the factory DCC button.", "price": "$1,500–2,800", "signal": "Reference kit", "links": []}, {"name": "Bilstein B14 (PSS) / B16 (PSS10 or DampTronic)", "note": "B14 fixed, B16 ten-click. The B16 DampTronic plugs into the DCC harness so the Mode menu still works; the standard B16 needs a canceller.", "price": "$1,300–2,600", "signal": "Daily-and-track pick", "links": []}, {"name": "ST X / XA / XTA", "note": "KW's value line, same install. XA adds damping; XTA adds camber plates. ST also sells adjustable-height lowering springs for DCC cars.", "price": "$1,000–1,800", "signal": "Value coilover", "links": []}, {"name": "Sachs Performance", "note": "OE-supplier kit; the FCP Euro install video this guide follows was done on one, with 034 camber plates.", "price": "$1,200–1,500", "signal": "Best documented", "links": [{"store": "FCP Euro install write-up and video", "url": "https://www.fcpeuro.com/blog/mk7-gti-sachs-performance-coilovers-034motorsport-camber-plate-install"}]}, {"name": "BC Racing BR", "note": "Camber plates and mounts included, 30-way damping, spring rates and strut diameter chosen at order. Softer bodies; the price shows.", "price": "$1,000–1,300", "signal": "Own mounts included", "links": []}, {"name": "Eibach Pro-Kit springs", "note": "Mild: about 1.1 in on the GTI (advertised less). Linear, DCC-friendly. The conservative choice.", "price": "$300–350", "signal": "Mild drop", "links": []}, {"name": "APR Roll-Control springs", "note": "Dual-rate, sold in DCC and non-DCC versions with different drops (22/37 mm DCC, 18/32 non-DCC). Designed not to ride on the bump stops.", "price": "$350–400", "signal": "DCC-specific engineering", "links": []}, {"name": "H&R Sport / EMD / CTS springs", "note": "H&R: about 1.6 in, firmer. EMD: made by Eibach, matched to the DCC dampers, half a notch stiffer than stock in each mode. CTS: about an inch, works with DCC per owners.", "price": "$250–400", "signal": "Fine choices", "links": []}], "tools": [{"name": "Jack, four stands, a second jack for the control arms; a length of 2×4 with a hole in it to hang the knuckle from (GolfMK7 trick)"}, {"name": "14 mm triple-square (pinch bolt) and 18 mm socket · 10 mm triple-square (axle flange) · 16 and 13 mm sockets · T20 (rear liner) · 17 mm thin-wall for lugs"}, {"name": "21 mm strut-nut socket or flange wrench with a 7 mm hex to hold the rod; 22 mm for camber-plate nuts"}, {"name": "Spring compressor (rent a good one)", "note": "needed for coilovers that reuse the factory mounts and for every spring install", "only": ["coil", "springs"]}, {"name": "Small chisel or shim for the anti-rotation tab, pry bar, soft mallet, penetrating oil, digital caliper, tape measure"}, {"name": "Torque wrench to 200 Nm and an angle gauge; VCDS or OBDeleven for the headlight leveling basic setting (xenon/LED cars)"}], "before": ["Measure fender-to-ground at all four corners on level ground and write it down. That's your height reference.", "Measure the front strut diameter and confirm it matches the box before you touch a bolt.", "Soak the pinch bolts, end-link nuts and axle-flange bolts the night before.", {"text": "Unplug the four DCC connectors before pulling anything; the cancellers plug in where they were.", "only": ["coil+dcc"]}, "Fronts first (harder), then rears. Both sides of an axle before you move on."], "steps": [{"n": 1, "title": "Measure, raise, wheels off", "blocks": [{"t": "text", "b": "Fender heights recorded, strut diameter confirmed. Raise the car on four stands, all wheels off (17 mm thin-wall)."}]}, {"n": 2, "title": "Front: disconnect around the strut", "blocks": [{"t": "text", "b": "Brake hose and ABS wire bracket off the strut (10 mm). End-link nut at the strut bracket: 16 or 18 mm, hex or triple-square in the stud's tip if it spins. Push the link out of the way."}, {"t": "text", "b": "Free the axle at the inner flange: six 10 mm triple-square bolts where the axle meets the transmission flange. A screwdriver through a rotor vane against the caliper holds the rotor still and lets you turn it to reach each bolt. Wire the shaft up out of the way.", "only": ["coil", "springs"]}, {"t": "note", "b": "The alternative is the Mk5 method: pull the hub off the outer CV joint instead. That needs the 200 Nm + 180° axle bolt loosened on the ground and replaced with a new one. FCP's flange route avoids it."}]}, {"n": 3, "title": "Front: pinch bolt, ball joint, anti-rotation tab", "caution": true, "blocks": [{"t": "text", "b": "Pinch bolt: 14 mm triple-square in the bolt head to hold it, 18 mm on the nut, breaker bar. Then the three 16 mm ball-joint nuts under the control arm; pry between the arm and the joint to separate them."}, {"t": "text", "b": "Now the part the Mk5 doesn't have: a spring-steel anti-rotation tab locks the strut into the knuckle's clamp. Push a shim or small chisel between the tab and the bracket to release it, with a helper or a jack supporting the knuckle so it doesn't fall forward. Tap the knuckle down off the strut."}, {"t": "ill", "id": "mk7-coilover-hero", "cap": "Front strut: one pinch bolt and the anti-rotation tab below, three bolts under the cowl above. Rear: spring in the arm, shock beside it."}, {"t": "warn", "b": "A seized pinch bolt is where the day goes. Oil, patience, and never hammer on the housing without the tab released; the clamp cracks."}]}, {"n": 4, "title": "Front: strut out from the top", "blocks": [{"t": "text", "b": "Pull the small clip and peel back the rubber cowl seal above the strut tower. Three 13 mm bolts. Break all three loose, leave one in while you remove the other two, one hand on the strut, then the last bolt and lower it out. Hang the knuckle from the 2×4 so the brake hose isn't carrying it."}]}, {"n": 5, "title": "Front: bench work", "caution": true, "blocks": [{"t": "text", "b": "Old strut in a vise. Spring compressor on, both claws, compressed until the spring lifts off the upper seat. Hold the rod with a 7 mm hex, remove the top nut with a 21 mm strut socket, lift off the mount and bearing."}, {"t": "warn", "b": "A compressed coil spring stores enough energy to kill. Claws seated, hooks facing each other, never over the ends of the spring. Bench only, never in the car."}, {"t": "fork", "q": "What are you building?", "v": [{"label": "Coilover", "when": "", "blocks": [{"t": "text", "b": "Light grease on the threads, perch and lock ring to the bottom. Spring on (taper down), kit's spacer, then the new bearing and either the factory-style mount or the kit's camber plate (match the bearing tabs to the plate). New top nut, rod held with the hex, 60 Nm. Wind the perch up until the spring just touches both seats; height comes later."}]}, {"label": "Lowering springs", "when": "", "blocks": [{"t": "text", "b": "Old spring off the factory strut, new spring on the same way round with the factory pads; some kits include a shorter bump stop, fit it. New bearing under the mount, new top nut, 60 Nm. Compressor off slowly."}]}]}, {"t": "torque", "label": "Front strut top nut", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm: GolfMK7 reference guide and MyGolfMk7. Kit-supplied nuts may differ; check."}}]}, {"n": 6, "title": "Front: into the car", "caution": true, "blocks": [{"t": "text", "b": "Up into the tower, three new mount bolts started. Jack the knuckle up and guide the strut's foot into the clamp until the anti-rotation tab clicks home; new pinch bolt through, nut on. Ball joint back into the arm, three new nuts. Axle flange bolts back in. Brake bracket. End link snug."}, {"t": "torque", "label": "Upper strut mount bolts (×3, NEW)", "nm": 15, "note": "+90° turn", "c": {"level": "high", "n": 3, "note": "15 Nm + 90°: GolfMK7 reference guide, VWVortex Koni DIY, MyGolfMk7."}}, {"t": "torque", "label": "Pinch bolt (M14, NEW)", "nm": 70, "note": "+180° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 180°, holding the triple-square while the nut turns. GolfMK7's guide was corrected from +90° to +180°; MyGolfMk7 lists the same value for the lower arm bolts."}}, {"t": "torque", "label": "Ball joint nuts (×3, NEW)", "nm": 40, "note": "+45° turn", "c": {"level": "single", "n": 1, "note": "40 Nm + 45° from MyGolfMk7's table. Not confirmed by a second source this pass."}}, {"t": "torque", "label": "Axle flange bolts (M10 12-point ×6)", "nm": 70, "c": {"level": "single", "n": 1, "note": "No MQB figure found this pass. 70 Nm is the value for the same M10 12-point flange bolts on the Mk5; FCP's video gives none. Flagged."}}, {"t": "text", "b": "Other side. Wheels on at 120 Nm; end-link nuts (65 Nm) once the car is on the ground."}]}, {"n": 7, "title": "Rear: liner and level sensor", "blocks": [{"t": "text", "b": "Wheel off. The fender liner comes out (many T20 screws; wear glasses, it drops grit). Driver's side: unbolt the headlight level sensor arm from the lower control arm first, before anything else, so you don't forget it and bend it."}]}, {"n": 8, "title": "Rear: shock and spring out", "blocks": [{"t": "text", "b": "Jack under the lower control arm. Working outward-in as GolfMK7 recommends: knuckle-to-arm bolt (18 mm both sides) first, then the lower shock bolt (18 mm), then the end-link bolt (13 mm). Tap each bolt through with a soft mallet, adjusting the jack until the bolt slides. Lower the jack slowly; the arm drops and the spring lifts out with its pads."}, {"t": "text", "b": "Two 16 mm bolts hold the shock's upper mount to the body. One hand on the shock, both bolts out, shock down."}]}, {"n": 9, "title": "Rear: build and fit", "blocks": [{"t": "text", "b": "Rear shock: new mount onto the rod with the factory dust cap, rod nut to 25 Nm. Set damping to the same click as the fronts.", "only": ["coil"]}, {"t": "text", "b": "Rear spring: the kit's adjuster replaces the top spring pad; the round end of the spring seats in the factory lower pad, the flat end against the adjuster. Set it to match the fronts.", "only": ["coil"]}, {"t": "text", "b": "Factory shock stays. New spring into the arm with the factory pads, same orientation as the old one (round end down). If the kit includes a rear spring pad or spacer, fit it now.", "only": ["springs"]}, {"t": "torque", "label": "Shock rod nut", "nm": 25, "c": {"level": "single", "n": 1, "note": "25 Nm from MyGolfMk7's table."}, "only": ["coil"]}, {"t": "text", "b": "Shock up, two upper bolts torqued. Jack the arm until the knuckle bolt slides in; lower shock bolt and end-link bolt through with their spacers. Nuts on, none tight."}, {"t": "torque", "label": "Rear shock upper mount bolts (×2)", "nm": 50, "note": "+45° turn", "c": {"level": "high", "n": 2, "note": "50 Nm + 45°: MyGolfMk7 and the FCP Euro procedure order."}}]}, {"n": 10, "title": "Rear torques at ride height", "caution": true, "blocks": [{"t": "text", "b": "The lower shock bolt, knuckle bolt and end-link bolt all clamp rubber bushings. Torqued in the air they'd be wound up at the wrong angle. Wheels on (120 Nm), lower the car onto its wheels or ramps, then torque all three."}, {"t": "torque", "label": "Rear knuckle-to-arm bolt (NEW)", "nm": 70, "note": "+180° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 180° at ride height: MyGolfMk7 (manual), GolfMK7 guide."}}, {"t": "torque", "label": "Rear shock lower bolt (NEW)", "nm": 70, "note": "+180° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 180°: MyGolfMk7 and GolfMK7. Not the Mk5's 180 Nm flat."}}, {"t": "torque", "label": "Rear end-link bolt (NEW)", "nm": 20, "note": "+180° turn", "c": {"level": "medium", "n": 1, "note": "20 Nm + 180° (MyGolfMk7, from the manual)."}}, {"t": "warn", "b": "On stands these are just snug. Torque only with the weight on the wheels. Forgetting this is how bushings tear in a month."}]}, {"n": 11, "title": "DCC cancellers", "only": ["coil+dcc"], "blocks": [{"t": "text", "b": "Plug one module into each of the four damper connectors you unplugged at the start, and zip-tie it clear of the spring, the wheel and anything hot. A DCC-compatible coilover (B16 DampTronic, KW DDC) plugs straight into those connectors instead; follow its sheet for the module."}, {"t": "note", "b": "The cancellers stop the fault and keep the rest of the chassis module working. They don't make the new dampers adjustable from the button; that's the plug-and-play kits."}]}, {"n": 12, "title": "Set ride height", "only": ["coil"], "blocks": [{"t": "text", "b": "Lift so the springs are unloaded, wind the perches to your target using the step-1 measurements (a sensible street drop is 1 to 1.5 in), lower, roll it a few feet, re-measure, repeat. Left and right within a few millimetres. Tighten the lock rings. Turn the wheel lock to lock and bounce each corner: nothing touches."}]}, {"n": 13, "title": "Check the drop", "only": ["springs"], "blocks": [{"t": "text", "b": "Springs settle over the first week; measure against step 1 after a few drives. Advertised drops are conservative; Eibach Pro-Kit owners measure about an inch where the box says less."}]}, {"n": 14, "title": "Headlights and alignment", "blocks": [{"t": "text", "b": "Xenon or LED headlights: the leveling system reads the sensor arms you moved, and it needs a basic setting after any ride-height change or the beams aim at the pavement. VCDS or OBDeleven, headlight range control module, basic settings. Then the alignment, next day, after the springs have settled. Re-check pinch bolts and end links at 100 miles."}]}], "alsoReplace": [{"name": "Strut bearings and mounts", "why": "They're off the strut. Notchy steering return and clunks over bumps come from these; the F-revision bearing is the current part.", "only": ["coil", "springs"]}, {"name": "Adjustable sway-bar end links", "why": "Lowering shortens the link geometry; adjustable links let the bars sit unloaded at the new height."}, {"name": "Rear shock mounts", "why": "Cheap rubber on a decade-old car; they're in your hand."}, {"name": "Camber correction (front plates or bolts; rear camber/toe arms)", "why": "Below about 1.5 in of drop the factory adjustment range runs out and the alignment shop will tell you so."}, {"name": "Rear subframe inserts", "why": "You're under there with the arms loose. The MQB rear subframe bushings are the source of the vague rear end owners complain about."}], "check": {"tab": "Which route?", "title": "Coilovers or springs, and how low?", "illId": "mk7-coilover-hero", "illCap": "Height and damping are separate decisions; DCC decides which kits are even on the table.", "rows": [{"see": "Daily driver, rough roads, DCC", "means": "You want a modest drop and to keep the button.", "do": "Springs (Eibach, EMD, APR DCC version). One inch, done."}, {"see": "Daily driver, no DCC, want adjustability", "means": "Height control without a huge budget.", "do": "ST X or Bilstein B14, 1 to 1.5 in, baseline damping."}, {"see": "Spirited street, occasional track", "means": "Adjustable damping earns its keep.", "do": "KW V2/V3, B16, ST XA; DampTronic or DDC if you have DCC. Adjustable end links and a little extra negative camber."}, {"see": "Show car", "means": "Looks first.", "do": "Go low, budget for camber correction, adjustable links, tire wear, and a canceller if DCC. Expect the ride to suffer."}], "c": {"level": "community", "n": 4, "note": "Forum consensus, vendor positioning, DCC compatibility from the vendor listings."}}, "aftercare": ["Alignment after settling; headlight basic setting on xenon/LED cars.", "Re-torque pinch bolts and end links at 100 miles; re-measure height at a week.", "Grease coilover threads and lock rings once a year in the salt belt or they seize.", "DCC fault after a canceller install: one module isn't seated or a connector pin is bent."], "disagreements": [{"topic": "Pinch bolt angle", "pos": "GolfMK7's guide originally said 70 Nm + 90°, later corrected to +180°.", "call": "+180°, which matches the manual-sourced table."}, {"topic": "Axle: flange or hub?", "pos": "FCP unbolts the inner flange (six bolts, no axle-bolt replacement). The Koni DIY pulls the hub off the outer joint with an axle puller.", "call": "Flange. Fewer single-use parts, no 200 Nm bolt."}, {"topic": "Strut diameter by trim", "pos": "'GTIs are 55 mm' vs owners with 50 mm GTIs; H&R confirmed both exist.", "call": "Measure. Thirty seconds with a caliper."}, {"topic": "DCC: code it out or cancel it?", "pos": "A shop coded DCC out on a customer car with standard B16s; vendors sell cancellers.", "call": "Cancellers or a compatible kit. Coding out is a workaround that can return with a software update."}, {"topic": "How much does the Pro-Kit drop?", "pos": "Eibach: 0.2 in front / 0.6 in rear. Owners: about an inch all round.", "call": "Expect an inch."}], "sources": ["FCP Euro 'How to install an Audi/VW coilover kit' (Mk7 GTI, Sachs + 034 plates, 2018)", "GolfMK7 'Spring & shock/damper installation reference guide' (2016, torque and part numbers)", "MyGolfMk7 torque spec table (MQB manuals)", "VWVortex Koni coilover install DIY (spreader tool, axle route)", "DAP 'Mk7 GTI coilovers and install DIY' (install kits, lighting-package note)", "KW 68510342, iSWEEP IS.EC.MK7 and Silvers DCC canceller listings", "VWVortex 'GTI strut diameter help', GolfMK7 '50 mm or 55 mm' threads", "VWVortex Eibach Pro-Kit with DCC thread; APR Roll-Control spring listing"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
